def main():
    rows = json.loads((ROOT / 'codex-config-schema.json').read_text())['rows']
    keys = [r['k'] for r in rows]
    gom = [k for k in keys if k not in R]
    ezafe = [k for k in R if k not in keys]
    if gom or ezafe:
        raise SystemExit(f'بی‌فارسی: {gom} · فارسیِ بی‌ردیف: {ezafe}')
    fa, tozih = {}, {}
    for k in keys:
        line, sharh, khali, extra = R[k]
        fa[k] = line
        e = {'sharh': sharh, 'khali': khali}
        e.update(extra)
        tozih[k] = e
    for name, data in (('codex-tanzimat-fa.json', fa), ('codex-tanzimat-tozih.json', tozih)):
        (ROOT / name).write_text(json.dumps(data, ensure_ascii=False, indent=1) + '\n')
    print(f'{len(keys)} ردیف نوشته شد')


if __name__ == '__main__':
    main()
